public Map<String, Boolean> hasH5Menu(String componentId, String versionNo,
                                     HttpServletRequest request) {
    // 用户身份只从登录态取，不接受前端传参
    String userName = casService.getLoginUserName(request);
    Map<String, Boolean> result = new HashMap<>(4);
    boolean has = componentMenuService.existsH5Menu(componentId, versionNo);
    result.put("hasH5Menu", has);
    if (!has) {
        result.put("hasReaded", true);      // 没有 H5 菜单就没必要弹，视为已读
        return result;
    }
    result.put("hasReaded", menuReadDao
            .existsByComponentIdAndVersionNoAndUserName(componentId, versionNo, userName));
    return result;
}

public void markReaded(String componentId, String versionNo, HttpServletRequest request) {
    String userName = casService.getLoginUserName(request);
    // 幂等：弹窗关闭可能触发多次，已存在直接返回，不靠唯一索引抛异常兜底
    if (menuReadDao.existsByComponentIdAndVersionNoAndUserName(componentId, versionNo, userName)) {
        return;
    }
    ComponentMenuRead read = new ComponentMenuRead();
    read.setComponentId(componentId);
    read.setVersionNo(versionNo);
    read.setUserName(userName);
    read.setCreateTime(new Date());
    menuReadDao.save(read);
}
